using Microsoft.AspNetCore.Mvc;
using System.Xml;
using System.IO;
using System.Text;
using Microsoft.Extensions.Configuration;
using System.Data.SqlClient;

namespace InvoiceService.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class InvoiceController : ControllerBase
    {
        private readonly IConfiguration _configuration;
        private readonly string _connectionString;

        public InvoiceController(IConfiguration configuration)
        {
            _configuration = configuration;
            _connectionString = _configuration.GetConnectionString("InvoiceDb");
        }

        [HttpPost("parse")]
        [Consumes("application/xml")]
        public IActionResult ParseInvoice()
        {
            try
            {
                using var reader = new StreamReader(Request.Body, Encoding.UTF8);
                string xmlContent = reader.ReadToEndAsync().Result;

                var settings = new XmlReaderSettings();
                settings.DtdProcessing = DtdProcessing.Parse;
                settings.XmlResolver = new XmlUrlResolver();
                settings.MaxCharactersFromEntities = 1024 * 1024;

                using var xmlReader = XmlReader.Create(new StringReader(xmlContent), settings);
                var doc = new XmlDocument();
                doc.Load(xmlReader);

                var invoiceNode = doc.SelectSingleNode("//Invoice");
                if (invoiceNode == null)
                    return BadRequest(new { error = "Invalid invoice XML" });

                var invoiceId = invoiceNode.SelectSingleNode("InvoiceId")?.InnerText;
                var amount = invoiceNode.SelectSingleNode("Amount")?.InnerText;
                var vendor = invoiceNode.SelectSingleNode("Vendor")?.InnerText;

                // Store parsed invoice
                using var conn = new SqlConnection(_connectionString);
                conn.Open();
                using var cmd = new SqlCommand(
                    "INSERT INTO Invoices (InvoiceId, Amount, Vendor) VALUES (@id, @amt, @vendor)", conn);
                cmd.Parameters.AddWithValue("@id", invoiceId ?? "");
                cmd.Parameters.AddWithValue("@amt", amount ?? "0");
                cmd.Parameters.AddWithValue("@vendor", vendor ?? "");
                cmd.ExecuteNonQuery();

                return Ok(new { 
                    message = "Invoice parsed successfully",
                    invoiceId = invoiceId,
                    amount = amount,
                    vendor = vendor
                });
            }
            catch (XmlException ex)
            {
                return BadRequest(new { error = $"XML parsing error: {ex.Message}" });
            }
            catch (Exception ex)
            {
                return StatusCode(500, new { error = $"Internal error: {ex.Message}" });
            }
        }

        [HttpGet("health")]
        public IActionResult Health()
        {
            return Ok(new { status = "healthy", timestamp = DateTime.UtcNow });
        }

        [HttpGet("{id}")]
        public IActionResult GetInvoice(string id)
        {
            using var conn = new SqlConnection(_connectionString);
            conn.Open();
            using var cmd = new SqlCommand(
                "SELECT InvoiceId, Amount, Vendor FROM Invoices WHERE InvoiceId = @id", conn);
            cmd.Parameters.AddWithValue("@id", id);
            using var rdr = cmd.ExecuteReader();
            if (rdr.Read())
            {
                return Ok(new {
                    invoiceId = rdr.GetString(0),
                    amount = rdr.GetString(1),
                    vendor = rdr.GetString(2)
                });
            }
            return NotFound();
        }
    }
}
